/* Standalone source-loading diagnostic. Uses the existing per-file read,
 * compile and execute timers; stops before constructing another runtime.
 * Run from mmvm_v2_tests:
 *   artifacts/js_runner.exe artifacts/snap guest_vm/tools/profile_source_loading.js
 * The loaded implementation remains the bootstrap compiler, not cached build
 * input. This reads and processes the current sources exactly as a rebuild's
 * source-loading stage does. Inclusive outer load timings must not be summed
 * with their nested file timings. No snapshot is generated by this tool. */
if (typeof GuestStandaloneProfile === "undefined" ||
    typeof GuestStandaloneFrontend === "undefined") {
    throw new Error("source-loading phase profiling requires a standalone image");
}
var sourceLoadingWasProfiling = GuestStandaloneProfile;
GuestStandaloneProfile = true;
/* Instrument the seed frontend, not the implementation about to be loaded.
 * Nested function sinks include verification/adoption. They run during
 * lowering, so subtract their inclusive time rather than summing both. */
var sourceProfileOriginalCompile = GuestStandaloneFrontend.compile;
var sourceProfileOriginalParse = GuestVMParser.prototype.parseProgram;
var sourceProfileActive = null;
GuestVMParser.prototype.parseProgram = function () {
    var started = new Date().getTime();
    try { return sourceProfileOriginalParse.apply(this, arguments); }
    finally {
        if (sourceProfileActive) sourceProfileActive.parseMs += new Date().getTime() - started;
    }
};
GuestStandaloneFrontend.compile = function (source, filename, options) {
    var previous = sourceProfileActive;
    var phase = {parseMs: 0, sinkMs: 0, functions: 0};
    var started = new Date().getTime();
    var originalSink = options && options.finishFunction;
    sourceProfileActive = phase;
    if (originalSink) {
        options.finishFunction = function (program) {
            var sinkStarted = new Date().getTime();
            try { return originalSink.call(this, program); }
            finally {
                phase.sinkMs += new Date().getTime() - sinkStarted;
                phase.functions++;
            }
        };
    }
    try { return sourceProfileOriginalCompile.call(this, source, filename, options); }
    finally {
        var total = new Date().getTime() - started;
        sourceProfileActive = previous;
        if (originalSink) options.finishFunction = originalSink;
        print("source phases: " + filename + " parse=" + phase.parseMs +
            " lower/analyze=" + (total - phase.parseMs - phase.sinkMs) +
            " nested-verify/adopt=" + phase.sinkMs +
            " functions=" + phase.functions + " total=" + total + "ms");
    }
};
GuestVM = undefined;
GuestNodeEnvironment = undefined;
var sourceLoadingStarted = new Date().getTime();
load("guest_vm/guest_vm.js");
load("guest_vm/node_environment.js");
print("source-loading total: " + (new Date().getTime() - sourceLoadingStarted) + "ms");
GuestStandaloneProfile = sourceLoadingWasProfiling;
